AssistantMessageToolRequest(name='create', tool_call_id='function-call-951873a5-4a02-44fe-9d7d-71456b6f020f', arguments={'file_text': 'const { useState } = React;

const FormField = ({ id, label, helperText, required, checked, onChange, error }) => {
    return (
        <div className="form-field">
            <div className="checkbox-wrapper" onClick={() => onChange(!checked)}>
                <input
                    id={id}
                    type="checkbox"
                    required={required}
                    checked={checked}
                    onChange={(e) => onChange(e.target.checked)}
                    aria-describedby={`${id}-helper ${error ? `${id}-error` : ''}`}
                    aria-invalid={!!error}
                    onClick={(e) => e.stopPropagation()} // Prevent double trigger from wrapper click
                />
                <label htmlFor={id} onClick={(e) => e.stopPropagation()}>
                    {label}
                    {required && <span className="required-star" aria-hidden="true">*</span>}
                </label>
            </div>
            <div id={`${id}-helper`} className="helper-text">
                {helperText}
            </div>
            {error && (
                <div id={`${id}-error`} className="error-message" role="alert">
                    Error: {error}
                </div>
            )}
        </div>
    );
};

const App = () => {
    const [agreed, setAgreed] = useState(false);
    const [error, setError] = useState('');
    const [submitted, setSubmitted] = useState(false);

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!agreed) {
            setError('You must agree to the terms of use to continue.');
            // Focus the checkbox for accessibility
            document.getElementById('consent-checkbox')?.focus();
            return;
        }

        setError('');
        setSubmitted(true);
        console.log('Form submitted successfully');
    };

    if (submitted) {
        return (
            <div className="container">
                <div className="success-message">
                    <h1>Thank you!</h1>
                    <p>Your consent has been recorded.</p>
                </div>
            </div>
        );
    }

    return (
        <div className="container">
            <h1>Registration</h1>
            <form onSubmit={handleSubmit} novalidate>
                <FormField
                    id="consent-checkbox"
                    label="I agree to the Terms of Use"
                    helperText="By checking this box, you confirm that you have read and accept our data privacy policy and usage guidelines."
                    required={true}
                    checked={agreed}
                    onChange={(val) => {
                        setAgreed(val);
                        if (val) setError('');
                    }}
                    error={error}
                />
                <button type="submit" className="submit-button">
                    Complete Registration
                </button>
            </form>
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
