    --bg-color: #121212;
    --card-bg: #1e1e1e;
    --text-primary: #e0e0e0;
    --text-secondary: #a0a0a0;
    --accent-color: #3d8af7;
    --accent-hover: #5a9cf9;
    --error-color: #cf6679;
    --focus-ring: 0 0 0 3px rgba(61, 138, 247, 0.5);
    --border-color: #333333;
}

body {
    margin: 0;
    padding: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-primary);
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

.container {
    background-color: var(--card-bg);
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
    width: 100%;
    max-width: 400px;
}

h1 {
    font-size: 1.5rem;
    margin-bottom: 1.5rem;
    text-align: center;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: white;
    padding: 8px;
    z-index: 100;
    transition: top 0.2s;
}

.skip-link:focus {
    top: 0;
}

.form-field {
    margin-bottom: 1.5rem;
}

.checkbox-wrapper {
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

input[type="checkbox"] {
    width: 20px;
    height: 20px;
    margin: 0;
    cursor: pointer;
    accent-color: var(--accent-color);
    flex-shrink: 0;
    margin-top: 3px;
}

input[type="checkbox"]:focus-visible {
    outline: none;
    box-shadow: var(--focus-ring);
    border-radius: 4px;
}

label {
    font-size: 1rem;
    line-height: 1.4;
    cursor: pointer;
    user-select: none;
}

.helper-text {
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-top: 8px;
    margin-left: 32px;
}

.required-star {
    color: var(--error-color);
    margin-left: 4px;
}

.error-message {
    color: var(--error-color);
    font-size: 0.85rem;
    margin-top: 8px;
    margin-left: 32px;
    font-weight: 500;
}

.submit-button {
    width: 100%;
    padding: 0.75rem;
    font-size: 1rem;
    font-weight: 600;
    background-color: var(--accent-color);
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    transition: background-color 0.2s ease;
}

.submit-button:hover {
    background-color: var(--accent-hover);
}

.submit-button:focus-visible {
    outline: none;
    box-shadow: var(--focus-ring);
}

.submit-button:active {
    transform: translateY(1px);
}

/* Success state */
.success-message {
    text-align: center;
    color: #4caf50;
    font-weight: 500;
}
