    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Success state */
.success-message {
    text-align: center;
    color: #4caf50;
    font-weight: 500;
}
