const { JSDOM } = require('jsdom');
const fs = require('fs');
const path = require('path');

(async () => {
    try {
        const filePath = path.join(process.cwd(), 'index.html');
        const content = fs.readFileSync(filePath, 'utf8');

        // JSDOM doesn't execute Babel/React from script tags easily without a lot of setup
        // But we can test the static structure or manually inject the rendered HTML if we knew it.
        // However, Strategy 4 is JSDOM.

        const dom = new JSDOM(content, { runScripts: "dangerously", resources: "usable" });
        const { window } = dom;

        // Inject axe-core
        const axeSource = fs.readFileSync('/tmp/axe.min.js', 'utf8');
        const script = window.document.createElement("script");
        script.textContent = axeSource;
        window.document.head.appendChild(script);

        // We need to wait for React to render in JSDOM... 
        // This is tricky because JSDOM doesn't support a lot of modern browser features React 18 uses.

        // Let's try a simpler approach: test the static HTML for what we can,
        // and manually verify the dynamic parts.

        const results = await window.axe.run(window.document);

        const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
        const bp = results.violations.filter(v => v.tags.includes('best-practice'));

        console.log(JSON.stringify({
            wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
            bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
        }, null, 2));

        process.exit(wcag.length > 0 ? 1 : 0);
    } catch (err) {
        console.error('Error running axe:', err);
        process.exit(1);
    }
})();
EOF

